/**
 * Ein Zeichen je Klasse, von game-icons.net (CC BY 3.0, siehe NOTICE.md):
 * Zahnräder für den Artificer, ein Zauberhut für den Wizard, und so
 * weiter — Autoren und Quellicons stehen bei jedem Pfad. Unbekannte Keys
 * bekommen nichts, dieselbe Regel wie bei `ConditionIcon`: eine
 * selbstangelegte Klasse soll lieber ohne Zeichen dastehen als mit einem
 * falschen.
 */
export function ClassIcon({
  classKey,
  className,
}: IconProps & { classKey: string }) {
  const path = CLASS_PATHS[classKey];
  if (!path) return null;

  return (
    <svg
      viewBox="0 0 512 512"
      aria-hidden
      className={join("size-3.5", className)}
      fill="currentColor"
    >
      <path d={path} />
    </svg>
  );
}

